#!/usr/bin/env bash
# Builds a release APK into dist/Kitsune-v<version>.apk.
#
# Uses the JDK + Android SDK in .toolchain/ when present, otherwise your JAVA_HOME / ANDROID_HOME.
# The android/ folder is generated by `expo prebuild` from app.json; never edit it by hand.
#
# Signing: if a release keystore is configured (KITSUNE_KEYSTORE_PROPERTIES, default
# ~/.kitsune/keystore.properties), the APK is re-signed with it. Keys live outside the repo.
set -euo pipefail
cd "$(dirname "$0")/.."
ROOT="$PWD"

[ -d .toolchain/jdk ] && export JAVA_HOME="$ROOT/.toolchain/jdk/Contents/Home"
[ -d .toolchain/android-sdk ] && export ANDROID_HOME="$ROOT/.toolchain/android-sdk"
: "${JAVA_HOME:?Set JAVA_HOME to a JDK 17 or newer}"
: "${ANDROID_HOME:?Set ANDROID_HOME to your Android SDK}"
export PATH="$JAVA_HOME/bin:$ANDROID_HOME/platform-tools:$PATH"

VERSION=$(node -p "require('./app.json').expo.version")
OUT="dist/Kitsune-v$VERSION.apk"

npx expo prebuild --platform android --no-install "$@"
(cd android && ./gradlew assembleRelease --console=plain)

mkdir -p dist
cp android/app/build/outputs/apk/release/app-release.apk "$OUT"

PROPS="${KITSUNE_KEYSTORE_PROPERTIES:-$HOME/.kitsune/keystore.properties}"
if [ -f "$PROPS" ]; then
  prop() { grep -E "^$1=" "$PROPS" | cut -d= -f2-; }
  APKSIGNER=$(ls -d "$ANDROID_HOME"/build-tools/*/apksigner | sort -V | tail -1)
  STORE_PASS=$(prop storePassword) KEY_PASS=$(prop keyPassword) "$APKSIGNER" sign \
    --ks "$(prop storeFile)" --ks-key-alias "$(prop keyAlias)" \
    --ks-pass env:STORE_PASS --key-pass env:KEY_PASS "$OUT"
  "$APKSIGNER" verify "$OUT"
  echo "Signed with release key from $PROPS"
else
  echo "No release keystore at $PROPS; APK is signed with the debug key."
fi

# Checksum names the bare file so `shasum -c` works next to a downloaded copy.
(cd dist && shasum -a 256 "$(basename "$OUT")") | tee "$OUT.sha256"
rm -f "$OUT.idsig"
echo "Built $ROOT/$OUT"
